import json
with open('/tmp/claude-0/-home-user-deepseek-harness/14a3dc14-c5aa-4250-a42c-9c1f33cd1814/scratchpad/npm-audit.json') as f:
    data = json.load(f)
vulns = data['vulnerabilities']
direct_names = {k for k,v in vulns.items() if v.get('isDirect')}

def reach_directs(name, seen=None):
    if seen is None: seen = set()
    if name in seen: return set()
    seen.add(name)
    if name in direct_names:
        return {name}
    effects = vulns.get(name, {}).get('effects', [])
    if not effects:
        return set()  # dead end, no direct dependency found (maybe dev-only orphan)
    result = set()
    for e in effects:
        result |= reach_directs(e, seen)
    return result

# for each direct dep, count how many OTHER vulnerable packages roll up to it (excluding itself)
from collections import defaultdict
owner_count = defaultdict(set)
unresolved = []
for name in vulns:
    if name in direct_names:
        continue
    directs = reach_directs(name)
    if not directs:
        unresolved.append(name)
    for d in directs:
        owner_count[d].add(name)

for d in sorted(direct_names):
    print(d, '-> transitive advisories count:', len(owner_count.get(d, [])))
print()
print('unresolved (no direct found):', len(unresolved))
print(unresolved[:50])
"
","description":"Group transitive vulnerable packages by direct dependency owner"}

